using System.Reflection;
using System.Text.Json;
using Yukkuri.Simulation;
int failures=0;
void Require(bool ok,string why){if(!ok)throw new Exception(why);}
void Near(double actual,double expected,string why)=>Require(Math.Abs(actual-expected)<1e-8,$"{why}: {actual} != {expected}");
void Check(string name,Action action){try{action();Console.WriteLine("PASS "+name);}catch(Exception e){failures++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
WorldSimulation Fresh(){var sim=WorldSimulation.CreateInteractionPlaytest();var c=sim.Selected!;sim.State.Creatures.RemoveAll(o=>o!=c);sim.State.RoomObjects.Clear();c.Personality.Kindness=0;c.Interaction.RuleLearning=0;c.Registration.Grade="未评级";c.Fullness=90;c.Energy=90;c.Fear=0;c.Pain=0;c.Trust=0;c.Attachment=0;c.Interaction.Hydration=90;c.Interaction.NextAutonomyAt=10000;return sim;}
void Waste(WorldSimulation s,int portions=20,string? region=null)=>s.State.RoomObjects.Add(new(){Kind=RoomObjectKind.Feces,Portions=portions,RegionId=region??s.Selected!.RegionId,X=3,Z=3});
var advance=typeof(WorldSimulation).GetMethod("AdvanceEmotionalContinuity",BindingFlags.NonPublic|BindingFlags.Instance)!;
void Mood(WorldSimulation s,double dt)=>advance.Invoke(s,new object[]{s.Selected!,dt});
WorldSimulation Reload(WorldSimulation s){SaveStore.Validate(s.State);var state=JsonSerializer.Deserialize<WorldState>(JsonSerializer.Serialize(s.State,SaveStore.JsonOptions),SaveStore.JsonOptions)!;SaveStore.Validate(state);return new(state);}
Check("kindness breakpoints and interpolation",()=>{var c=Fresh().Selected!;foreach(var (x,y) in new[]{(0d,0d),(.15,0),(.4,46),(.65,92),(.825,95.5),(1,99)}){c.Personality.Kindness=x;Near(EnvironmentHygiene.Requirement(c),y,"kindness");}double previous=0;for(int i=0;i<=1000;i++){c.Personality.Kindness=i/1000d;double now=EnvironmentHygiene.Requirement(c);Require(now>=previous&&now<=99,"monotonic bounded");previous=now;}});
Check("education breakpoints and interpolation",()=>{var c=Fresh().Selected!;foreach(var (x,y) in new[]{(0d,0d),(25,45),(50,90),(75,94.5),(100,99)}){c.Interaction.RuleLearning=x;Near(EnvironmentHygiene.Requirement(c),y,"education");}});
Check("all existing license aliases and ungraded",()=>{var c=Fresh().Selected!;foreach(var (names,expected) in new[]{("未评级,unknown",0d),("铜,铜牌,Bronze",24d),("银,银牌,Silver",48d),("金,金牌,Gold",72d),("白金,白金牌,Platinum",96d)})foreach(string name in names.Split(',')){c.Registration.Grade=name;Near(EnvironmentHygiene.Requirement(c),expected,name);}});
Check("maximum of three curves not additive or proficiency based",()=>{var c=Fresh().Selected!;c.Personality.Kindness=.65;c.Interaction.RuleLearning=50;c.Registration.Grade="金";Near(EnvironmentHygiene.Requirement(c),92,"kindness wins");c.Interaction.RuleLearning=75;Near(EnvironmentHygiene.Requirement(c),94.5,"education wins");c.Registration.Grade="白金";Near(EnvironmentHygiene.Requirement(c),96,"license wins");c.Interaction.RuleLearning=100;Near(EnvironmentHygiene.Requirement(c),99,"maximum");c.Personality.Kindness=0;c.Interaction.RuleLearning=0;c.Registration.Grade="未评级";c.Interaction.CleaningLearning=100;Near(EnvironmentHygiene.Requirement(c),0,"proficiency not requirement");});
Check("exact deficit multiplier zero and sixty cap",()=>{var s=Fresh();var c=s.Selected!;c.Personality.Kindness=.65;Near(EnvironmentHygiene.Discomfort(s.State,c),0,"clean");Waste(s,1);Near(EnvironmentHygiene.Discomfort(s.State,c),0,"equal");s.State.RoomObjects[0].Portions=2;Near(EnvironmentHygiene.Discomfort(s.State,c),5.2,"eight deficit");c.Personality.Kindness=1;s.State.RoomObjects[0].Portions=20;Near(EnvironmentHygiene.Discomfort(s.State,c),60,"cap");c.Personality.Kindness=.15;Near(EnvironmentHygiene.Discomfort(s.State,c),0,"tolerant");});
Check("individual region and live traits objects",()=>{var s=Fresh();var c=s.Selected!;c.Personality.Kindness=1;Waste(s,20,"woodland");s.State.ActiveRegionId="woodland";Near(EnvironmentHygiene.Discomfort(s.State,c),0,"own region");c.RegionId="woodland";Near(EnvironmentHygiene.Discomfort(s.State,c),60,"move");s.State.RoomObjects[0].Stored=true;Near(EnvironmentHygiene.Discomfort(s.State,c),0,"stored");s.State.RoomObjects[0].Stored=false;c.Personality.Kindness=0;Near(EnvironmentHygiene.Discomfort(s.State,c),0,"trait change");});
Check("actual emotion descent and recovery preserve original rates",()=>{var s=Fresh();var c=s.Selected!;c.Personality.Kindness=1;c.Interaction.Emotion.Manmanlai=65;Mood(s,1);Near(c.Interaction.Emotion.Manmanlai,65,"clean target");Waste(s);Mood(s,1);Near(c.Interaction.Emotion.Manmanlai,63.8,"gradual down");for(int i=0;i<100;i++)Mood(s,1);Near(c.Interaction.Emotion.Manmanlai,5,"target reached");s.State.RoomObjects.Clear();Mood(s,1);Near(c.Interaction.Emotion.Manmanlai,5.15,"gradual recovery");for(int i=0;i<500;i++)Mood(s,1);Near(c.Interaction.Emotion.Manmanlai,65,"recovered");});
Check("tolerant mood unchanged and no direct trust health change",()=>{var s=Fresh();var c=s.Selected!;Waste(s);c.Interaction.Emotion.Manmanlai=65;Mood(s,1);Near(c.Interaction.Emotion.Manmanlai,65,"tolerant");c.Personality.Kindness=1;double trust=c.Trust,health=c.Health;Mood(s,1);Near(c.Trust,trust,"trust");Near(c.Health,health,"health");});
Check("zero delta and cold storage freeze emotional update",()=>{var s=Fresh();var c=s.Selected!;c.Personality.Kindness=1;Waste(s);c.Interaction.Emotion.Manmanlai=65;Mood(s,0);Near(c.Interaction.Emotion.Manmanlai,65,"zero dt");c.Family.ColdStorage.Stored=true;Mood(s,1);Near(c.Interaction.Emotion.Manmanlai,65,"cold");});
Check("public world pause and close-up freeze mood",()=>{var s=Fresh();var c=s.Selected!;c.Personality.Kindness=1;Waste(s);c.Interaction.Emotion.Manmanlai=65;s.State.Settings.Pause=true;s.Advance(1);s.AdvanceInteractionPresentation(1);Near(c.Interaction.Emotion.Manmanlai,65,"pause");s.State.Settings.Pause=false;s.State.Mode=PlayMode.CloseUp;s.Advance(1);s.AdvanceInteractionPresentation(1);Near(c.Interaction.Emotion.Manmanlai,65,"close-up");s.State.Mode=PlayMode.Management;s.Advance(.25);Require(c.Interaction.Emotion.Manmanlai<65,"resume");});
Check("save reload derives requirement and resumes emotion",()=>{var s=Fresh();var c=s.Selected!;c.Personality.Kindness=.65;c.Interaction.RuleLearning=75;c.Registration.Grade="白金";Waste(s,2);c.Interaction.Emotion.Manmanlai=40;var r=Reload(s);Near(EnvironmentHygiene.Requirement(r.Selected!),96,"requirement");Near(EnvironmentHygiene.Discomfort(r.State,r.Selected!),7.8,"discomfort");Near(r.Selected!.Interaction.Emotion.Manmanlai,40,"mood stored");Mood(r,1);Near(r.Selected.Interaction.Emotion.Manmanlai,40.15,"resume gradual");r.State.RoomObjects.Clear();Near(EnvironmentHygiene.Discomfort(r.State,r.Selected),0,"no stale cache");});
Check("feedback reports target penalty without instant mood claim",()=>{var s=Fresh();s.Selected!.Personality.Kindness=1;Waste(s);string text=EnvironmentHygiene.DescribeIndividual(s.State,s.Selected);Require(text.Contains("99/100")&&text.Contains("60")&&text.Contains("目标扣值"),"feedback");});
Console.WriteLine($"Individual hygiene: {failures} failures");return failures==0?0:1;
